extension UIColor {
    /// sRGB color from a value in **web order** `0xRRGGBBAA` (alpha last, as in tokens.json).
    convenience init(bbRGBA value: UInt32) {
        self.init(
            red: CGFloat((value >> 24) & 0xFF) / 255,
            green: CGFloat((value >> 16) & 0xFF) / 255,
            blue: CGFloat((value >> 8) & 0xFF) / 255,
            alpha: CGFloat(value & 0xFF) / 255
