}

extension Color {
    /// Light/dark color resolved per trait collection, so it follows both the system appearance
    /// and the in-app theme override (`preferredColorScheme` / `overrideUserInterfaceStyle`).
    init(bbLight light: UInt32, dark: UInt32) {
        if light == dark {
            self.init(uiColor: UIColor(bbRGBA: light))
        } else {
            self.init(uiColor: UIColor { traits in
                UIColor(bbRGBA: traits.userInterfaceStyle == .dark ? dark : light)
            })
        }
    }
}

