// MARK: - Fonts

/// Bundled font families (static instances in Resources/Fonts, registered via UIAppFonts).
enum BBFontRole: String, CaseIterable, Sendable {
    case sans
    case display
    case mono

    var familyName: String {
        switch self {
        case .sans: "Hanken Grotesk"
        case .display: "Sofia Sans Extra Condensed"
        case .mono: "system-monospace"
        }
    }

    /// True for a platform font (nothing bundled): render with the system font of that design.
    var isSystem: Bool {
        switch self {
        case .sans: false
        case .display: false
        case .mono: true
        }
    }

    /// Bundled weights and their PostScript names.
    var faces: [(weight: Int, postScriptName: String)] {
        switch self {
        case .sans: [(400, "HankenGrotesk-Regular"), (500, "HankenGrotesk-Medium"), (600, "HankenGrotesk-SemiBold"), (700, "HankenGrotesk-Bold")]
        case .display: [(300, "SofiaSansExtraCondensed-Light"), (400, "SofiaSansExtraCondensed-Regular")]
        case .mono: []
        }
    }

    /// PostScript name of the bundled instance closest to `weight` (empty for a system family).
    func postScriptName(weight: Int) -> String {
        faces.min { abs($0.weight - weight) < abs($1.weight - weight) }?.postScriptName ?? ""
    }

    /// Font files to list under `UIAppFonts`.
    static let fontFiles: [String] = [
        "HankenGrotesk-Regular.ttf",
        "HankenGrotesk-Medium.ttf",
        "HankenGrotesk-SemiBold.ttf",
        "HankenGrotesk-Bold.ttf",
        "SofiaSansExtraCondensed-Light.ttf",
        "SofiaSansExtraCondensed-Regular.ttf",
    ]
}

